const items = $input.all();

const MAX_FILES = 10;
const MAX_CHARS_PER_FILE = 15000;
const MAX_TOTAL_CHARS = 60000;

const scripts = [];
const logs = [];
const metrics = [];
const configurations = [];
const contextFiles = [];
const unsupportedFiles = [];
const filesReceived = [];

let problemDescription = '';
let totalCharacters = 0;

/*
 * Extensii de cod sursă.
 */
const scriptLanguages = {
  py: 'python',
  js: 'javascript',
  mjs: 'javascript',
  cjs: 'javascript',
  ts: 'typescript',
  sh: 'shell',
  ps1: 'powershell',
  sql: 'sql'
};

const configurationExtensions = new Set([
  'yml',
  'yaml',
  'conf',
  'ini',
  'toml',
  'xml'
]);

function getExtension(filename) {
  const parts = String(filename).toLowerCase().split('.');

  return parts.length > 1
    ? parts.pop()
    : '';
}

function normalizeText(buffer) {
  return buffer
    .toString('utf8')
    .replace(/\u0000/g, '')
    .replace(/^\uFEFF/, '');
}

function limitedContent(text) {
  const remaining = Math.max(
    0,
    MAX_TOTAL_CHARS - totalCharacters
  );

  const limit = Math.min(
    MAX_CHARS_PER_FILE,
    remaining
  );

  const content = text.slice(0, limit);

  totalCharacters += content.length;

  return {
    content,
    original_character_count: text.length,
    truncated:
      text.length > content.length
  };
}

function looksLikeLog(filename, text) {
  const name = filename.toLowerCase();

  if (
    name.includes('log') ||
    name.includes('error') ||
    name.includes('trace') ||
    name.includes('output') ||
    name.includes('stderr') ||
    name.includes('stdout')
  ) {
    return true;
  }

  const beginning = text.slice(0, 3000);

  return (
    /\b(ERROR|WARN|WARNING|INFO|DEBUG|TRACE|FATAL)\b/.test(beginning) ||
    /\d{4}-\d{2}-\d{2}[T\s]\d{2}:\d{2}/.test(beginning) ||
    /Traceback \(most recent call last\)/.test(beginning)
  );
}

function looksLikeMetrics(filename, text) {
  const name = filename.toLowerCase();

  if (
    name.includes('metric') ||
    name.includes('monitor') ||
    name.includes('performance') ||
    name.includes('cpu') ||
    name.includes('memory')
  ) {
    return true;
  }

  const firstLine = text
    .split(/\r?\n/, 1)[0]
    .toLowerCase();

  return (
    firstLine.includes('cpu') ||
    firstLine.includes('memory') ||
    firstLine.includes('latency') ||
    firstLine.includes('response_time') ||
    firstLine.includes('error_rate')
  );
}

function looksLikeConfiguration(filename) {
  const name = filename.toLowerCase();

  return (
    name.includes('config') ||
    name.includes('compose') ||
    name.includes('docker') ||
    name.includes('nginx') ||
    name.includes('settings') ||
    name.includes('environment') ||
    name.endsWith('.env')
  );
}

/*
 * Identifică problema raportată.
 */
for (const item of items) {
  if (problemDescription) {
    break;
  }

  if (item.json?.problem_description) {
    problemDescription = String(
      item.json.problem_description
    ).trim();

    break;
  }

  const problemKey = Object.keys(item.json ?? {}).find(
    (key) =>
      key.toLowerCase().includes('problem')
  );

  if (problemKey) {
    problemDescription = String(
      item.json[problemKey] ?? ''
    ).trim();
  }
}

/*
 * Citește și clasifică toate fișierele.
 */
let processedFiles = 0;

for (
  let itemIndex = 0;
  itemIndex < items.length;
  itemIndex++
) {
  const item = items[itemIndex];

  for (
    const [binaryKey, file] of Object.entries(
      item.binary ?? {}
    )
  ) {
    const filename = String(
      file.fileName ?? binaryKey
    );

    const extension = getExtension(filename);

    filesReceived.push({
      filename,
      extension,
      mime_type: file.mimeType ?? '',
      size_bytes: Number(file.fileSize ?? 0)
    });

    if (processedFiles >= MAX_FILES) {
      unsupportedFiles.push({
        filename,
        reason: `Limita de ${MAX_FILES} fișiere a fost depășită`
      });

      continue;
    }

    if (totalCharacters >= MAX_TOTAL_CHARS) {
      unsupportedFiles.push({
        filename,
        reason: 'Limita totală de text a fost atinsă'
      });

      continue;
    }

    const buffer =
      await this.helpers.getBinaryDataBuffer(
        itemIndex,
        binaryKey
      );

    const text = normalizeText(buffer);

    /*
     * Evită trimiterea fișierelor binare către model.
     */
    const nullByteCount =
      (buffer.subarray(0, 5000).toString('latin1')
        .match(/\x00/g) ?? []).length;

    if (nullByteCount > 10) {
      unsupportedFiles.push({
        filename,
        extension,
        reason: 'Fișier binar sau format text nesuportat'
      });

      continue;
    }

    const limited = limitedContent(text);

    const commonData = {
      filename,
      extension,
      mime_type: file.mimeType ?? '',
      size_bytes: buffer.length,
      content: limited.content,
      original_character_count:
        limited.original_character_count,
      truncated: limited.truncated
    };

    /*
     * Scripturi.
     */
    if (
      Object.hasOwn(
        scriptLanguages,
        extension
      )
    ) {
      scripts.push({
        ...commonData,
        language: scriptLanguages[extension]
      });

      processedFiles++;
      continue;
    }

    /*
     * Loguri.
     */
    if (
      extension === 'log' ||
      (
        extension === 'txt' &&
        looksLikeLog(filename, text)
      )
    ) {
      logs.push(commonData);
      processedFiles++;
      continue;
    }

    /*
     * Metrici.
     */
    if (
      extension === 'csv' ||
      looksLikeMetrics(filename, text)
    ) {
      metrics.push(commonData);
      processedFiles++;
      continue;
    }

    /*
     * Configurații.
     */
    if (
      configurationExtensions.has(extension) ||
      (
        extension === 'json' &&
        looksLikeConfiguration(filename)
      )
    ) {
      configurations.push(commonData);
      processedFiles++;
      continue;
    }

    /*
     * JSON, TXT, MD sau alte fișiere text folosite
     * drept context.
     */
    if (
      [
        'json',
        'txt',
        'md'
      ].includes(extension)
    ) {
      contextFiles.push(commonData);
      processedFiles++;
      continue;
    }

    unsupportedFiles.push({
      filename,
      extension,
      reason: 'Extensie nesuportată'
    });
  }
}

const availableSources = [];

if (scripts.length > 0) {
  availableSources.push('scripts');
}

if (logs.length > 0) {
  availableSources.push('logs');
}

if (metrics.length > 0) {
  availableSources.push('metrics');
}

if (configurations.length > 0) {
  availableSources.push('configurations');
}

if (contextFiles.length > 0) {
  availableSources.push('context');
}

return [{
  json: {
    problem_description: problemDescription,

    has_scripts: scripts.length > 0,
    has_logs: logs.length > 0,
    has_metrics: metrics.length > 0,
    has_configurations:
      configurations.length > 0,
    has_context_files:
      contextFiles.length > 0,

    scripts,
    logs,
    metrics,
    configurations,
    context_files: contextFiles,

    files_received: filesReceived,
    unsupported_files: unsupportedFiles,

    analysis_mode:
      availableSources.length > 0
        ? availableSources.join('+')
        : 'no_supported_sources',

    processed_file_count: processedFiles,
    total_character_count: totalCharacters
  }
}];

